{
  "compilerOptions": {
    // --- BUILD PROCESS ---
    "target": "ES2022",
    "module": "ESNext",
    "outDir": "./dist",
    "sourceMap": true, // Generates .map files so browser debuggers show TS code

    // --- LINTING & QUALITY ---
    "noUnusedLocals": true, // Errors if a variable is declared but never read
    "noImplicitReturns": true, // Errors if some branches of a function don't return a value

    // --- REACT ---
    "jsx": "react-jsx" // Required for React 17+ to understand <div> syntax
  }
}
